class Solution {
public:
    long long maxArrayValue(vector<int>& nums) {
        int n = nums.size();
        long long current = nums[n - 1];
        long long answer = current;
        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] <= current) {
                current += nums[i];
            } else {
                current = nums[i];
            }
            if (current > answer) {
                answer = current;
            }
        }
        return answer;
    }
};
